from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Field names used throughout, centralised to avoid typos.
_GRID = "grid"
_OBSERVATIONS = "observations"
_FILL_VALUE = "fill_value"


def accumulate_grid(raw: object) -> dict:
    """Aggregate observations onto a grid.

    Public behaviour is preserved: returns either an error dict or a success
    dict with averaged cells, per-cell flags and aggregate statistics.
    """
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if _GRID not in raw or _OBSERVATIONS not in raw or _FILL_VALUE not in raw:
        return {"ok": False, "error": "missing field"}

    grid = raw[_GRID]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw[_FILL_VALUE], int):
        return {"ok": False, "error": "bad fill value"}

    observations = raw[_OBSERVATIONS]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    state = _GridAccumulator(cell_size, width, height)

    for obs in observations:
        error = _validate_observation(obs)
        if error is not None:
            return {"ok": False, "error": error}

        if obs["quality"] < MIN_QUALITY:
            state.rejected += 1
            continue
        state.place(obs)

    cells = _averaged_rows(state.sums, state.counts, width, height, raw[_FILL_VALUE])
    flags = _flag_rows(state.counts, state.degraded, width, height)
    coverage = _coverage(state.counts, width, height)
    line = _summary_line(
        width * height,
        len(state.counts),
        state.dropped,
        state.rejected,
        state.saturated,
        coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": state.dropped,
        "rejected": state.rejected,
        "saturated": state.saturated,
        "coverage": coverage,
        "line": line,
    }


class _GridAccumulator:
    """Mutable per-call state for the observation aggregation loop."""

    __slots__ = ("cell_size", "width", "height", "tolerance",
                 "sums", "counts", "degraded", "dropped", "rejected", "saturated")

    def __init__(self, cell_size: int, width: int, height: int) -> None:
        self.cell_size = cell_size
        self.width = width
        self.height = height
        self.tolerance = cell_size // 2
        self.sums: dict = {}
        self.counts: dict = {}
        self.degraded: dict = {}
        self.dropped = 0
        self.rejected = 0
        self.saturated = 0

    def place(self, obs: dict) -> None:
        """Drop or accumulate a single (already quality-filtered) observation."""
        x = obs["x"]
        if x < 0:
            self.dropped += 1
            return
        col = x // self.cell_size
        if col >= self.width:
            if x - self.width * self.cell_size < self.tolerance:
                col = self.width - 1
            else:
                self.dropped += 1
                return

        y = obs["y"]
        if y < 0:
            self.dropped += 1
            return
        row = y // self.cell_size
        if row >= self.height:
            if y - self.height * self.cell_size < self.tolerance:
                row = self.height - 1
            else:
                self.dropped += 1
                return

        key = (row, col)
        if self.counts.get(key, 0) >= SATURATION_LIMIT:
            self.saturated += 1
            return
        self.sums[key] = self.sums.get(key, 0) + obs["value"]
        self.counts[key] = self.counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            self.degraded[key] = True


def _validate_observation(obs: object) -> str | None:
    """Return an error message if the observation is malformed, else ``None``.

    The checks mirror the original validation order exactly.
    """
    if not isinstance(obs, dict):
        return "bad observation"
    if "x" not in obs or not isinstance(obs["x"], int):
        return "bad observation"
    if "y" not in obs or not isinstance(obs["y"], int):
        return "bad observation"
    if "value" not in obs or not isinstance(obs["value"], int):
        return "bad observation"
    if "quality" not in obs or not isinstance(obs["quality"], int):
        return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
